{"code":"import random

def generate(rng):
    # Background field of sparse 1s on 0, with a dense rectangular 8/1 panel.
    h = rng.randint(9, 30); w = rng.randint(9, 30)
    g = [[1 if rng.random() < 0.18 else 0 for _ in range(w)] for _ in range(h)]
    ph = rng.randint(max(3, h//4), max(3, min(h-2, h//2+2)))
    pw = rng.randint(max(3, w//4), max(3, min(w-2, w//2+2)))
    r0 = rng.randint(1, h-ph-1) if h-ph-1 >= 1 else 0
    c0 = rng.randint(1, w-pw-1) if w-pw-1 >= 1 else 0
    for r in range(r0, r0+ph):
        for c in range(c0, c0+pw):
            g[r][c] = 8 if rng.random() < 0.48 else 1
    return g"}

